const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// Database configuration\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// -----------------------------------------------------------------------------\n// 1. System Settings\n// -----------------------------------------------------------------------------\nmodel SystemConfig {\n  id Int @id @default(autoincrement())\n\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  currency          Currency?\n  unitPrice         Decimal?\n  smallBoxCapacity  Int       @default(50)\n  mediumBoxCapacity Int       @default(30)\n  largeBoxCapacity  Int       @default(24)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// -----------------------------------------------------------------------------\n// 2. Fields Settings\n// -----------------------------------------------------------------------------\nmodel Field {\n  id   Int    @id @default(autoincrement())\n  name String\n\n  fieldHarvests FieldHarvest[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  slug String @unique // URL-friendly slug\n\n  @@unique([name])\n}\n\n// -----------------------------------------------------------------------------\n// 3. Default Trader Categories (Global Defaults)\n// -----------------------------------------------------------------------------\nmodel DefaultTraderCategory {\n  id    Int     @id @default(autoincrement())\n  name  String  @unique\n  notes String?\n\n  shares DefaultTraderCategoryShare[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// -----------------------------------------------------------------------------\n// 4. Default Trader Category Shares\n// -----------------------------------------------------------------------------\nmodel DefaultTraderCategoryShare {\n  id Int @id @default(autoincrement())\n\n  traderId Int\n  trader   Trader @relation(fields: [traderId], references: [id], onDelete: Cascade)\n\n  defaultTraderCategoryId Int\n  defaultTraderCategory   DefaultTraderCategory @relation(fields: [defaultTraderCategoryId], references: [id], onDelete: Cascade)\n\n  percent Decimal\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([traderId, defaultTraderCategoryId])\n}\n\n// -----------------------------------------------------------------------------\n// 5. Season Management (The Time-Tenant)\n// -----------------------------------------------------------------------------\nmodel Season {\n  id       Int     @id @default(autoincrement())\n  yearName Int     @unique // e.g. \"2026\"\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  slug String @unique // URL-friendly slug\n\n  // \n  systemConfigs        SystemConfig[]\n  TradersCategories    TradersCategories[]\n  customerCategories   CustomerCategories[]\n  traderCategoryShares TraderCategoryShare[]\n  fieldHarvests        FieldHarvest[]\n  classifications      Classification[]\n  traderStocks         TraderStock[]\n  customerAllocations  CustomerAllocation[]\n  shipment             Shipment[]\n  box                  Box[]\n  shipmentItem         ShipmentItem[]\n}\n\n// -----------------------------------------------------------------------------\n// 6. User Management\n// -----------------------------------------------------------------------------\nmodel User {\n  id           Int     @id @default(autoincrement())\n  name         String  @unique\n  email        String  @unique\n  phone        String? @unique\n  passwordHash String\n  role         Role    @default(WORKER)\n  isActive     Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  slug String @unique // URL-friendly slug\n\n  // Relations\n  fieldHarvests       FieldHarvest[]\n  classifications     Classification[]\n  traderStocks        TraderStock[]\n  customerAllocations CustomerAllocation[]\n  shipment            Shipment[]\n  box                 Box[]\n  shipmentItem        ShipmentItem[]\n  sentMessages        Message[]            @relation(\"SentMessages\")\n}\n\n// -----------------------------------------------------------------------------\n// 7. Traders\n// -----------------------------------------------------------------------------\nmodel Trader {\n  id   Int    @id @default(autoincrement())\n  name String @unique\n\n  paymentPercent Decimal @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  slug String @unique // URL-friendly slug\n\n  // Relations\n  defaultCategoryShares DefaultTraderCategoryShare[]\n  traderCategoryShares  TraderCategoryShare[]\n  classifications       Classification[]\n  traderStocks          TraderStock[]\n  customerAllocations   CustomerAllocation[]\n  box                   Box[]\n  shipmentItem          ShipmentItem[]\n}\n\n// -----------------------------------------------------------------------------\n// 8. Customer\n// -----------------------------------------------------------------------------\nmodel Customer {\n  id           Int     @id @default(autoincrement())\n  customerName String  @unique\n  email        String? @unique\n  phone        String? @unique\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  slug String @unique // URL-friendly slug\n\n  // Relations\n  prices          CustomerCategories[]\n  allocations     CustomerAllocation[]\n  classifications Classification[]\n  box             Box[]\n  shipmentItem    ShipmentItem[]\n\n  @@index([customerName])\n}\n\n// -----------------------------------------------------------------------------\n// 9. Traders categories\n// -----------------------------------------------------------------------------\nmodel TradersCategories {\n  id       Int     @id @default(autoincrement())\n  name     String // Category name (e.g., \"Yanover\")\n  notes    String?\n  seasonId Int\n  season   Season  @relation(fields: [seasonId], references: [id])\n\n  isDefault Boolean @default(false) // true = created by SeedService bootstrap, false = manually added\n\n  traderCategoryShares TraderCategoryShare[]\n  classifications      Classification[]\n  traderStocks         TraderStock[]\n  shipmentItems        ShipmentItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([name, seasonId])\n}\n\n// -----------------------------------------------------------------------------\n// 10. Customer categories and prices\n// -----------------------------------------------------------------------------\nmodel CustomerCategories {\n  id       Int    @id @default(autoincrement())\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  customerId Int\n  customer   Customer @relation(fields: [customerId], references: [id])\n\n  name     String\n  grade    String\n  price    Decimal  @default(0)\n  currency Currency\n\n  classifications     Classification[]\n  customerAllocations CustomerAllocation[]\n  shipmentItems       ShipmentItem[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([seasonId, customerId, name, grade])\n}\n\n// -----------------------------------------------------------------------------\n// 11. Trader Category Share (%)\n// -----------------------------------------------------------------------------\nmodel TraderCategoryShare {\n  id Int @id @default(autoincrement())\n\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  traderId Int\n  trader   Trader @relation(fields: [traderId], references: [id])\n\n  traderCategoryId Int\n  traderCategory   TradersCategories @relation(fields: [traderCategoryId], references: [id])\n\n  percent Decimal\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([traderId, traderCategoryId, seasonId])\n}\n\n// -----------------------------------------------------------------------------\n// 12. Field Operations\n// -----------------------------------------------------------------------------\nmodel FieldHarvest {\n  id Int @id @default(autoincrement())\n\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  dateGregorian DateTime\n  dateHebrew    String\n  fieldId       Int\n  field         Field    @relation(fields: [fieldId], references: [id])\n\n  updatedById Int\n  updatedBy   User @relation(fields: [updatedById], references: [id])\n\n  totalHarvested Int     @default(0)\n  totalRejected  Int     @default(0)\n  rejectionRate  Decimal @default(0)\n\n  totalAfterRejected Int @default(0)\n\n  ownerHarvested     Int     @default(0)\n  ownerRejected      Int     @default(0)\n  ownerRejectionRate Decimal @default(0)\n\n  ownerAfterRejected Int @default(0)\n\n  classifiedTotal         Int     @default(0)\n  isPartialClassification Boolean @default(false)\n\n  notes String?\n\n  slug String @unique // URL-friendly ID (date-field-season)\n\n  // Relations\n  classifications Classification[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  isDeleted Boolean @default(false)\n\n  @@unique([seasonId, dateGregorian, fieldId]) // Prevent duplicate reports per season\n  @@index([seasonId])\n  @@index([seasonId, fieldId])\n  @@index([isDeleted])\n}\n\n// -----------------------------------------------------------------------------\n// 13. Grading & Classification\n// -----------------------------------------------------------------------------\nmodel Classification {\n  id Int @id @default(autoincrement())\n\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  fieldHarvestId Int\n  fieldHarvest   FieldHarvest @relation(fields: [fieldHarvestId], references: [id])\n\n  updatedById Int\n  updatedBy   User @relation(fields: [updatedById], references: [id])\n\n  assignmentType AssignmentType\n  traderId       Int?\n  trader         Trader?        @relation(fields: [traderId], references: [id])\n  customerId     Int?\n  customer       Customer?      @relation(fields: [customerId], references: [id])\n\n  traderCategoryId Int?\n  traderCategory   TradersCategories? @relation(fields: [traderCategoryId], references: [id])\n\n  customerCategoryId Int?\n  customerCategory   CustomerCategories? @relation(fields: [customerCategoryId], references: [id])\n\n  grade       Grade?\n  pitamStatus PitamStatus\n  quantity    Int         @default(0)\n\n  notes String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  slug String @unique // URL-friendly slug\n\n  isDeleted Boolean @default(false)\n\n  @@unique([fieldHarvestId, traderCategoryId, customerCategoryId, grade, assignmentType])\n  @@index([seasonId])\n  @@index([seasonId, fieldHarvestId])\n  @@index([seasonId, assignmentType])\n  @@index([seasonId, traderId])\n  @@index([seasonId, customerId])\n  @@index([isDeleted])\n}\n\n// -----------------------------------------------------------------------------\n// 14. Trader Inventory & Buffer Management\n// -----------------------------------------------------------------------------\nmodel TraderStock {\n  id Int @id @default(autoincrement())\n\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  date DateTime\n\n  traderId Int? // null if Modulo\n  trader   Trader? @relation(fields: [traderId], references: [id])\n\n  traderCategoryId Int\n  traderCategory   TradersCategories @relation(fields: [traderCategoryId], references: [id])\n\n  grade       Grade\n  pitamStatus PitamStatus\n  quantity    Int         @default(0)\n  isModulo    Boolean     @default(false)\n\n  type MovementType @default(HARVEST_IN)\n\n  MovementReferenceId Int? // classificationId, shipmentItemId or customerAllocationsId\n\n  shipmentId Int?\n  boxId      Int?\n  box        Box? @relation(fields: [boxId], references: [id])\n\n  notes String?\n\n  updatedById Int\n  updatedBy   User @relation(fields: [updatedById], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  isDeleted Boolean @default(false)\n\n  @@index([seasonId, type])\n  @@index([seasonId, traderId, type])\n  @@index([traderCategoryId, grade, pitamStatus, type])\n  @@index([isDeleted])\n}\n\n// -----------------------------------------------------------------------------\n// 15. Customer Allocations (Sales)\n// -----------------------------------------------------------------------------\nmodel CustomerAllocation {\n  id Int @id @default(autoincrement())\n\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  date       DateTime\n  dateHebrew String\n\n  customerId Int\n  customer   Customer @relation(fields: [customerId], references: [id])\n\n  customerCategoryId Int\n  customerCategory   CustomerCategories @relation(fields: [customerCategoryId], references: [id])\n\n  pitamStatus PitamStatus\n  quantity    Int\n\n  type MovementType @default(HARVEST_IN)\n\n  takenFrom        SourceType @default(GENERAL)\n  traderId         Int?\n  traderSourceName Trader?    @relation(fields: [traderId], references: [id])\n\n  MovementReferenceId Int? // classificationId, shipmentItemId or traderStockId\n\n  shipmentId Int?\n  boxId      Int?\n\n  notes String?\n\n  updatedById Int\n  updatedBy   User @relation(fields: [updatedById], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  isDeleted Boolean @default(false)\n\n  @@index([seasonId, type])\n  @@index([seasonId, customerId, type])\n  @@index([customerId, traderId, type])\n  @@index([customerCategoryId, pitamStatus, type])\n  @@index([isDeleted])\n}\n\n// -----------------------------------------------------------------------------\n// 16. Shipment\n// -----------------------------------------------------------------------------\nmodel Shipment {\n  id Int @id @default(autoincrement())\n\n  shipmentNumber Int @unique @default(autoincrement())\n\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  totalBoxes    Int @default(0)\n  totalQuantity Int @default(0)\n\n  status    ShipmentStatus @default(PREPARING)\n  shippedAt DateTime?\n\n  notes String?\n\n  // Relations: One Shipment -> Many Boxes -> Many Items\n  boxes Box[]\n  items ShipmentItem[]\n\n  updatedById Int\n  updatedBy   User @relation(fields: [updatedById], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  slug String @unique\n\n  isDeleted Boolean @default(false)\n\n  @@unique([seasonId, shipmentNumber])\n  @@index([seasonId])\n  @@index([seasonId, status])\n  @@index([isDeleted])\n}\n\n// -----------------------------------------------------------------------------\n// 17. Box - Container\n// -----------------------------------------------------------------------------\nmodel Box {\n  id         Int      @id @default(autoincrement())\n  shipmentId Int\n  shipment   Shipment @relation(fields: [shipmentId], references: [id])\n\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  boxNumber     Int // e.g., Box #1 in Shipment X\n  boxType       BoxType\n  totalQuantity Int     @default(0)\n\n  status BoxStatus @default(OPEN)\n\n  notes String?\n\n  // Relations: One Box -> Many Items\n  items        ShipmentItem[]\n  traderStocks TraderStock[]\n\n  // Ownership\n  ownershipType BoxOwnership @default(UNASSIGNED)\n  traderId      Int? // optional, if ownershipType = TRADER\n  trader        Trader?      @relation(fields: [traderId], references: [id])\n  customerId    Int? // optional, if ownershipType = CUSTOMER\n  customer      Customer?    @relation(fields: [customerId], references: [id])\n\n  updatedById Int\n  updatedBy   User @relation(fields: [updatedById], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  isDeleted Boolean @default(false)\n\n  @@unique([seasonId, boxNumber])\n  @@index([seasonId])\n  @@index([shipmentId])\n  @@index([traderId])\n  @@index([customerId])\n  @@index([seasonId, status])\n  @@index([traderId, status])\n  @@index([customerId, status])\n  @@index([isDeleted])\n}\n\n// -----------------------------------------------------------------------------\n// 18. Items - Products\n// -----------------------------------------------------------------------------\nmodel ShipmentItem {\n  id         Int      @id @default(autoincrement())\n  shipmentId Int\n  shipment   Shipment @relation(fields: [shipmentId], references: [id])\n\n  boxId Int\n  box   Box @relation(fields: [boxId], references: [id])\n\n  seasonId Int\n  season   Season @relation(fields: [seasonId], references: [id])\n\n  // Product Specs (Snapshot of what was packed)\n  traderCategoryId Int?\n  traderCategory   TradersCategories? @relation(fields: [traderCategoryId], references: [id])\n\n  customerCategoryId Int?\n  customerCategory   CustomerCategories? @relation(fields: [customerCategoryId], references: [id])\n\n  grade       Grade?\n  pitamStatus PitamStatus\n  quantity    Int\n\n  notes String?\n\n  // Ownership\n  ownershipType ItemOwnership @default(UNASSIGNED)\n  traderId      Int? // optional, if ownershipType = TRADER\n  trader        Trader?       @relation(fields: [traderId], references: [id])\n  customerId    Int? // optional, if ownershipType = CUSTOMER\n  customer      Customer?     @relation(fields: [customerId], references: [id])\n\n  updatedById Int\n  updatedBy   User @relation(fields: [updatedById], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  isDeleted Boolean @default(false)\n\n  @@unique([seasonId, boxId, traderCategoryId, customerCategoryId, grade, pitamStatus, ownershipType, traderId, customerId])\n  @@index([shipmentId])\n  @@index([boxId])\n  @@index([seasonId])\n  @@index([customerId])\n  @@index([seasonId, shipmentId])\n  @@index([traderId, shipmentId])\n  @@index([customerId, shipmentId])\n  @@index([isDeleted])\n}\n\n// -----------------------------------------------------------------------------\n// 19. Internal Messaging System\n// -----------------------------------------------------------------------------\nmodel Message {\n  id Int @id @default(autoincrement())\n\n  senderId Int\n  sender   User @relation(\"SentMessages\", fields: [senderId], references: [id], onDelete: Cascade)\n\n  recipientIds Int[] @default([])\n  readByIds    Int[] @default([])\n\n  replyToMessageId Int?\n  replyToMessage   Message?  @relation(\"MessageReplies\", fields: [replyToMessageId], references: [id])\n  replies          Message[] @relation(\"MessageReplies\")\n\n  subject  String\n  content  String   @db.Text\n  priority Priority @default(NORMAL)\n\n  createdAt DateTime @default(now())\n\n  @@index([senderId])\n  @@index([replyToMessageId])\n}\n\n// -----------------------------------------------------------------------------\n// Enums\n// -----------------------------------------------------------------------------\nenum Role {\n  OWNER\n  MANAGER\n  EDITOR\n  WORKER\n}\n\nenum PitamStatus {\n  WITH_PITAM\n  WITHOUT_PITAM\n  MIXED\n}\n\nenum Grade {\n  א\n  ב\n  ג\n  ד\n  ה\n  ו\n}\n\nenum AssignmentType {\n  GENERAL\n  TRADER\n  CUSTOMER\n}\n\nenum SourceType {\n  GENERAL\n  TRADER\n}\n\nenum Priority {\n  LOW\n  NORMAL\n  HIGH\n  URGENT\n}\n\nenum MovementType {\n  // --- Inbound Operations ---\n  HARVEST_IN // Initial entry from field sorting/grading (Positive)\n\n  // --- Inventory Logic & Ownership Transfers ---\n  INTERNAL_TRANSFER // Transfer between Trader <-> Customer\n  OWNERSHIP_TRANSFER // Transfer between Trader <-> Trader\n  ASSIGNED // Assigned from general pool (Modulo) to trader\n\n  // --- Physical Outbound Operations ---\n  PACKED_SHIPPED // Goods physically left the warehouse via shipment (Negative)\n  SELF_PICKUP // Goods physically collected by the owner/customer (Negative)\n\n  // --- Adjustments & Losses ---\n  WASTE // Spoilage, damage, or quality rejection (Negative)\n  ADJUSTMENT // Manual inventory correction for typos or audits (Positive/Negative)\n}\n\nenum ShipmentStatus {\n  PREPARING // Not yet departed\n  SHIPPED // Gone from warehouse\n  DELIVERED // Reached customer\n  CANCELLED // Reverted\n}\n\nenum BoxStatus {\n  OPEN // Editing allowed\n  CLOSED // Packed and sealed\n  SHIPPED // Dispatched\n}\n\nenum BoxType {\n  SMALL\n  MEDIUM\n  LARGE\n  CUSTOM\n}\n\nenum BoxOwnership {\n  TRADER\n  CUSTOMER\n  SHARED\n  UNASSIGNED\n  CUSTOM\n}\n\nenum ItemOwnership {\n  TRADER\n  CUSTOMER\n  UNASSIGNED\n  CUSTOM\n}\n\nenum Currency {\n  ILS\n  USD\n  EUR\n}\n"
}

